query SkillPool($sessionId: Urn!) {
  session(id: $sessionId) {
    id
    currentGal
    privacyMode
    skillPoolTokensCurrent
    skillPoolTokensBudget
    skillStates(tier: L3) {
      id
      skillId
      skillName
      tier
      score
      transitions {
        timestamp
        fromTier
        toTier
        trigger
      }
    }
  }
}
